mapper.select:
SELECT p.* , u.nickname AS created_by_nickname , (SELECT COUNT(*) FROM place_photos ph WHERE ph.place_id = p.place_id) AS photo_count FROM places p JOIN users u ON u.user_id = p.created_by WHERE p.collection_id = #{collectionId}
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.address LIKE CONCAT('%', #{keyword}, '%') OR p.tags LIKE CONCAT('%', #{keyword}, '%') OR p.memo LIKE CONCAT('%', #{keyword}, '%'))
AND p.category = #{category}
AND p.visited_yn = #{visitedYn}
ORDER BY p.created_at DESC

SELECT  *
FROM    (
            SELECT  p.*
            ,       (6371000 * ACOS(
                        COS(RADIANS(#{lat})) * COS(RADIANS(p.lat))
                        * COS(RADIANS(p.lng) - RADIANS(#{lng}))
                        + SIN(RADIANS(#{lat})) * SIN(RADIANS(p.lat))
                    )) AS distance_m
            FROM    places p
            WHERE   p.collection_id = #{collectionId}
        ) t
WHERE   t.distance_m <= #{radiusM}
ORDER BY t.distance_m

mapper.update:
UPDATE places
name = #{name}, address = #{address}, lat = #{lat}, lng = #{lng}, category = #{category}, tags = #{tags}, memo = #{memo}, visited_yn = #{visitedYn}, rating = #{rating}, opening_hours = #{openingHours}, phone = #{phone}, website = #{website},
WHERE place_id = #{placeId}

